 "risks": [
  {
   "id": "no_governing_law",
   "severity": "medium",
   "message": "The SOW has no governing law or jurisdiction clause of its own and defers to an MSA that is not included, so the applicable law and forum are unclear for Northwind.",
   "quote": "This SOW is governed by the terms of the Master Services Agreement between the Parties."
  },
  {
   "id": "no_liability_cap",
   "severity": "medium",
   "message": "No liability cap appears in this SOW. Northwind's exposure depends on the MSA, which was not provided and should be reviewed.",
   "quote": "This SOW is governed by the terms of the Master Services Agreement between the Parties."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The SOW has a fixed 36-month term and no termination right. Northwind may be locked in for the full term if the MSA does not provide an exit.",
   "quote": "This Agreement will remain in effect for thirty-six months from the Effective Date."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "low",
   "message": "The SOW has no confidentiality terms. Protection for Northwind's data in this migration depends on the MSA.",
   "quote": "This SOW is governed by the terms of the Master Services Agreement between the Parties."
  },
  {
   "id": "milestones_undefined",
   "severity": "low",
   "message": "The $120,000 fee is payable against milestones, but the SOW does not set out the milestone schedule or amounts. Acceptance depends on an Appendix A that was not provided.",
   "quote": "payable against milestones"
  },
  {
   "id": "term_fee_mismatch",
   "severity": "low",
   "message": "The 36-month term is long for a fixed-fee migration project, and the SOW does not say how it relates to the milestone timeline.",
   "quote": "This Agreement will remain in effect for thirty-six months from the Effective Date."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a Statement of Work between Northwind Labs, Inc. and Saltmarsh Analytics Pty Ltd for a data platform migration. It has a fixed fee of $120,000 payable against milestones, a 36-month term from 2026-07-04, and 30-day payment terms. Liability, governing law and confidentiality are left to a Master Services Agreement that was not provided."
}
